INSERT INTO faqs (question, answer, sort_order) VALUES
  ('When is admission open?', 'Admission runs throughout the year, subject to space. Send an enquiry to check availability for your child''s class.', 0),
  ('How much are the fees?', 'Fees depend on the class. Send an admission enquiry and we''ll send you the full fee schedule.', 1),
  ('Is there an entrance assessment?', 'Yes, a short, friendly assessment helps us place your child in the right class.', 2),
  ('Do you offer school transport?', 'Ask us about our bus routes and availability in your area.', 3),
